import * as React from 'react';
import { CardContent, Grid, IconButton, InputAdornment, TextField, Tooltip, Fab, Button } from '@mui/material';
// project imports
import MainCard from 'ui-component/cards/MainCard';
import { useDispatch, useSelector } from 'store';

import { getSubscriptionList, getPlansList } from 'store/slices/userPlans';

// assetss
import EditIcon from '@mui/icons-material/Edit';
import PrintIcon from '@mui/icons-material/PrintTwoTone';
import AddIcon from '@mui/icons-material/AddTwoTone';
import DynamicTable from 'views/commons/tables/DynamicTable';
import DeleteIcon from '@mui/icons-material/Delete';
import DeleteAlert from 'views/commons/alerts/deleteAlarts';
import useSnackbar from 'hooks/useSnackbar';
import GenericModelForm from 'views/commons/modelform/GenericModleForm';
import ApiRequest from 'utils/apiService';
import RenderDetails from './RenderDetails';
import { useTheme } from '@mui/material/styles';
import useAuth from 'hooks/useAuth';
import GenericSearchFilter from 'views/commons/search/GenericSearchFilter';
import FilterListIcon from '@mui/icons-material/FilterList';
import { getClientTableFields, getClientSearchFields } from 'store/constant';
import useTableManagement from 'hooks/useTableManagement';
import PaymentDetails from 'views/application/membership/payments/detailPayment';

const Subscriptions = () => {
    const { user } = useAuth();
    const theme = useTheme();
    const dispatch = useDispatch();
    const { entities } = useSelector((state) => state.userPlans);
    const subscriptions = entities.subscriptions || [];
    const allplans = entities.plans || [];
    const [open, setOpen] = React.useState(false);
    const [deleteDialogOpen, setDeleteDialogOpen] = React.useState(false);
    const [selectedIds, setSelectedIds] = React.useState([]);
    const { showSnackbar } = useSnackbar();
    const [editData, setEditData] = React.useState(null);
    const [searchParams, setSearchParams] = React.useState({}); // ✅ Stores search filter params
    const [filterOpen, setFilterOpen] = React.useState(false);

    const {
        rowsPerPage,
        page,
        totalRecords, // ✅ Get total from Redux
        orderBy,
        order,
        handlePageChange,
        handleRowsPerPageChange,
        handleSortChange,
        handleSearch,
        handleFilters,
        handleSelectAll,
        handleRowClick,
        selected,
        setSelected,
        loading,
        fetchData,
        setLoading
    } = useTableManagement({ fetchFunction: getSubscriptionList });

    const handleEdit = (row) => {
        dispatch(getPlansList({ pagination: false }));
        setEditData(row); // ✅ Store the selected row data
        setOpen(true); // ✅ Open modal
    };
    const handleDelete = (selectedIds) => {
        if (selectedIds.length === 0) return;
        setSelectedIds(selectedIds);
        setDeleteDialogOpen(true);
    };

    const handleClickOpenDialog = () => {
        dispatch(getPlansList({ pagination: false }));
        setOpen(true);
    };
    const handleCloseDialog = () => {
        setOpen(false);
        setEditData(null);
    };
    const handlePermissionSubmit = async (data, resetForm) => {
        setLoading(true);

        const url = editData ? `/membership/clients/edit/${editData.id}` : '/auth/signup';
        const method = editData ? 'PUT' : 'POST';
        const defaultMessage = editData ? 'Client Update successfully!' : 'Client Add successfully!';

        // ✅ Initialize payload with submitted data
        const payload = { ...data };
        payload.plan_ids = data?.plans.map((plan) => plan.id); // ✅ Add existing roles

        if (method === 'POST' && data?.plans.length > 0) {
            payload.createPlan = true;
            payload.roles = [{ id: 3, name: 'client' }];
        }

        try {
            const response = await ApiRequest(method, url, payload);
            showSnackbar(response.message || defaultMessage, 'success');
            dispatch(getSubscriptionList({ limit: rowsPerPage, page, ...searchParams, sortBy: orderBy, order, Client: 'Client' }));
            resetForm();
        } catch (error) {
            showSnackbar(error.message, 'error');
        } finally {
            setLoading(false);
            setOpen(false);
            setEditData(null);
        }
    };

    const handleReset = () => {
        setSearchParams({});
        fetchData({}); // ✅ Directly call fetchData with empty filters
    };

    return (
        <MainCard content={false} sx={{ background: theme.palette.text.primary, border: `3px solid ${theme.palette.primary.dark}` }}>
            <CardContent>
                <Grid container justifyContent="space-between" alignItems="right" spacing={0}>
                    <Grid item xs={12} sm={12} sx={{ textAlign: 'right' }}>
                        <Tooltip title="Print">
                            <IconButton size="large">
                                <PrintIcon />
                            </IconButton>
                        </Tooltip>
                        <Tooltip title="Filter">
                            <IconButton size="large" onClick={() => setFilterOpen(!filterOpen)}>
                                <FilterListIcon />
                            </IconButton>
                        </Tooltip>
                        {/* product add & dialog */}
                        <Tooltip title="Add Client">
                            <Fab
                                color="primary"
                                size="small"
                                onClick={handleClickOpenDialog}
                                sx={{ boxShadow: 'none', ml: 1, width: 32, height: 32, minHeight: 32 }}
                            >
                                <AddIcon fontSize="small" />
                            </Fab>
                        </Tooltip>

                        <GenericModelForm
                            open={open}
                            handleCloseDialog={handleCloseDialog}
                            position="center"
                            fields={getClientTableFields(allplans)}
                            onSubmit={handlePermissionSubmit}
                            formLabel={editData ? 'Edit Client' : 'Add Client'}
                            editData={editData}
                        />
                    </Grid>
                </Grid>
                <Grid container justifyContent="space-between" alignItems="center" spacing={0}>
                    <Grid item xs={12} sm={12}>
                        <GenericSearchFilter
                            fields={getClientSearchFields(allplans)}
                            onSearch={(values) => {
                                setSearchParams(values); // ✅ Update search state
                                handleFilters(values); // ✅ Trigger API with new search values
                            }}
                            onFilter={handleFilters} // need to remvoe
                            onReset={handleReset} // ✅ Pass reset handler
                            searchValues={searchParams} // ✅ Use `searchParams`
                            setSearchValues={setSearchParams} // ✅ Use `setSearchParams`
                            searchMode="manual"
                            expanded={filterOpen}
                            setExpanded={setFilterOpen}
                            loading={loading}
                        />
                    </Grid>
                </Grid>
                <DynamicTable
                    columns={[
                        { id: 'id', label: 'ID', align: 'center', sortable: true },
                        {
                            id: 'user.name',
                            label: 'User Name',
                            align: 'left',
                            sortable: false
                        },
                        {
                            id: 'user.email',
                            label: 'Email',
                            align: 'left',
                            sortable: false
                        },
                        {
                            id: 'plan.name',
                            label: 'Plan Name',
                            align: 'center',
                            sortable: false
                        },
                        {
                            id: 'status',
                            label: 'Subscription Status',
                            align: 'center',
                            sortable: false,
                            // Custom status labels
                            statusLabels: {
                                active: 'Active Subscription',
                                inactive: 'Subscription Inactive',
                                pending: 'Payment Pending'
                            }
                        }
                    ]}
                    data={subscriptions}
                    total={totalRecords}
                    page={page}
                    rowsPerPage={rowsPerPage}
                    onPageChange={handlePageChange}
                    onRowsPerPageChange={handleRowsPerPageChange}
                    order={order}
                    orderBy={orderBy}
                    onRequestSort={handleSortChange}
                    selected={selected || []}
                    onSelectAllClick={handleSelectAll} // ✅ Pass select all function
                    onRowClick={handleRowClick} // ✅ Pass row selection function
                    onDelete={handleDelete} // ✅ Pass delete function
                    showCheckbox // ✅ Add this to show checkboxes
                    collapsible
                    customtheme="light"
                    renderDetails={(row) => <RenderDetails row={row} />}
                    renderActions={(row) => (
                        <>
                            <Button onClick={() => handleEdit(row)} variant="outlined" size="small" color="error">
                                Cancel
                            </Button>
                        </>
                    )}
                    loading={loading}
                    customize={theme.palette.mode === 'dark'}
                />
            </CardContent>
            <DeleteAlert
                open={deleteDialogOpen}
                onClose={() => setDeleteDialogOpen(false)}
                selectedIds={selectedIds}
                endpoint="/users/delete"
                onDeleteSuccess={() => {
                    showSnackbar('User deleted successfully!', 'success');
                    fetchData({}, () => {
                        setDeleteDialogOpen(false);
                        setSelected([]);
                        setSelectedIds([]); // ✅ Clear selection after delete
                    });
                }}
                message="Are you sure you want to delete the selected permissions?"
            />
        </MainCard>
    );
};

export default Subscriptions;
