// utils/dateUtils.js

const formatDate = (isoString, formatType = 'full') => {
    if (!isoString) return 'Invalid Date';

    const date = new Date(isoString);

    switch (formatType) {
        case 'full':
            return new Intl.DateTimeFormat('en-US', {
                year: 'numeric',
                month: 'long', // Full month name (e.g., "February")
                day: '2-digit',
                hour: '2-digit',
                minute: '2-digit',
                second: '2-digit',
                hour12: true,
                timeZoneName: 'short' // Show timezone (e.g., "GMT")
            }).format(date);

        case 'short':
            return new Intl.DateTimeFormat('en-US', {
                year: 'numeric',
                month: 'short', // Short month (e.g., "Feb")
                day: '2-digit'
            }).format(date);

        case 'time':
            return new Intl.DateTimeFormat('en-US', {
                hour: '2-digit',
                minute: '2-digit',
                second: '2-digit',
                hour12: true
            }).format(date);

        default:
            return 'Invalid Format Type';
    }
};

export default formatDate; // ✅ Now using default export
