import React from 'react';
import {
    Box,
    Typography,
    Divider,
    Grid,
    Paper,
    Chip,
    Button,
    Stack,
    Avatar,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    useTheme
} from '@mui/material';
import { Receipt as InvoiceIcon, CreditCard as PaymentIcon, Description as PlanIcon, Person as UserIcon } from '@mui/icons-material';

const RenderDetails = ({ row }) => {
    const theme = useTheme();

    return (
        <Box sx={{ p: 0, width: '100%' }}>
            {/* Header */}
            <Paper elevation={0} sx={{ p: 2, mb: 3, background: '#F2F7F8' }}>
                <Stack direction="row" alignItems="center" spacing={2}>
                    <Avatar sx={{ bgcolor: theme.palette.secondary.main }}>
                        <PaymentIcon />
                    </Avatar>
                    <Typography variant="h5">Subscription Details</Typography>
                    <Chip label={row.status} color={row.status === 'active' ? 'success' : 'error'} sx={{ ml: 2 }} />
                </Stack>
            </Paper>

            <Grid container spacing={2}>
                {/* Invoices Section */}
                <Grid item xs={12}>
                    <Paper
                        elevation={0}
                        sx={{ p: 2, border: `1px solid ${theme.palette.divider}`, borderRadius: 2, background: '#F2F7F8', boxShadow: 3 }}
                    >
                        <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 2 }}>
                            <InvoiceIcon color="primary" />
                            <Typography variant="h6">Invoices</Typography>
                        </Stack>

                        <TableContainer>
                            <Table size="small">
                                <TableHead>
                                    <TableRow>
                                        <TableCell>Invoice ID</TableCell>
                                        <TableCell align="center">Amount</TableCell>
                                        <TableCell align="center">Date</TableCell>
                                        <TableCell align="center">Status</TableCell>
                                        <TableCell align="right">Actions</TableCell>
                                    </TableRow>
                                </TableHead>
                                <TableBody>
                                    {row.invoices.map((invoice) => (
                                        <TableRow key={invoice.id} sx={{ '& td': { color: 'black' } }}>
                                            <TableCell>
                                                <Typography sx={{ color: 'black' }} variant="body2" noWrap>
                                                    {invoice.providerInvoiceId}
                                                </Typography>
                                            </TableCell>
                                            <TableCell color="primary" align="center">
                                                ${(invoice.amountDue / 100).toFixed(2)}
                                            </TableCell>
                                            <TableCell align="center">{new Date(invoice.invoiceDate).toLocaleDateString()}</TableCell>
                                            <TableCell align="center">
                                                <Chip
                                                    label={invoice.status}
                                                    size="small"
                                                    color={invoice.status === 'paid' ? 'success' : 'warning'}
                                                />
                                            </TableCell>
                                            <TableCell align="right">
                                                <Button
                                                    variant="outlined"
                                                    size="small"
                                                    disabled={!invoice?.hostedInvoiceUrl}
                                                    onClick={() => {
                                                        const url = invoice?.hostedInvoiceUrl;
                                                        if (url) {
                                                            // Safely open in new tab
                                                            const newWindow = window.open(url, '_blank', 'noopener,noreferrer');
                                                        }
                                                    }}
                                                >
                                                    View Invoice
                                                </Button>
                                            </TableCell>
                                        </TableRow>
                                    ))}
                                </TableBody>
                            </Table>
                        </TableContainer>

                        {row.invoices.length === 0 && (
                            <Box sx={{ p: 3, textAlign: 'center' }}>
                                <Typography variant="body2" color="textSecondary">
                                    No invoices available
                                </Typography>
                            </Box>
                        )}
                    </Paper>
                </Grid>

                {/* Plan Details Section */}
                <Grid item xs={12} md={6}>
                    <Paper
                        elevation={0}
                        sx={{
                            p: 2,
                            border: `1px solid ${theme.palette.divider}`,
                            borderRadius: 2,
                            background: '#F2F7F8',
                            boxShadow: 3,
                            height: '100%'
                        }}
                    >
                        <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 2 }}>
                            <PlanIcon color="primary" />
                            <Typography variant="h6">Plan Details</Typography>
                        </Stack>

                        <TableContainer>
                            <Table size="small">
                                <TableHead>
                                    <TableRow sx={{ '& td': { color: 'black' } }}>
                                        <TableCell sx={{ width: '40%' }}>Attribute</TableCell>
                                        <TableCell sx={{ width: '60%' }}>Value</TableCell>
                                    </TableRow>
                                </TableHead>
                                <TableBody>
                                    <TableRow sx={{ '& td': { color: 'black' } }}>
                                        <TableCell>Plan Name</TableCell>
                                        <TableCell>{row.plan.name}</TableCell>
                                    </TableRow>
                                    <TableRow sx={{ '& td': { color: 'black' } }}>
                                        <TableCell>Description</TableCell>
                                        <TableCell>{row.plan.description || 'N/A'}</TableCell>
                                    </TableRow>
                                    <TableRow sx={{ '& td': { color: 'black' } }}>
                                        <TableCell>Billing Type</TableCell>
                                        <TableCell>{row.plan.plan_type}</TableCell>
                                    </TableRow>
                                    <TableRow sx={{ '& td': { color: 'black' } }}>
                                        <TableCell>Monthly Price</TableCell>
                                        <TableCell>${row.plan.price_monthly}</TableCell>
                                    </TableRow>
                                    <TableRow sx={{ '& td': { color: 'black' } }}>
                                        <TableCell>Annual Price</TableCell>
                                        <TableCell>${row.plan.price_annually}</TableCell>
                                    </TableRow>
                                    <TableRow sx={{ '& td': { color: 'black' } }}>
                                        <TableCell>Number of Accounts</TableCell>
                                        <TableCell>{row.plan.number_of_accounts}</TableCell>
                                    </TableRow>
                                    <TableRow sx={{ '& td': { color: 'black' } }}>
                                        <TableCell>Status</TableCell>
                                        <TableCell>
                                            <Chip
                                                label={row.plan.status ? 'Active' : 'Inactive'}
                                                size="small"
                                                color={row.plan.status ? 'success' : 'error'}
                                            />
                                        </TableCell>
                                    </TableRow>
                                </TableBody>
                            </Table>
                        </TableContainer>

                        <Box sx={{ mt: 2, display: 'flex', justifyContent: 'space-between' }}>
                            <Button variant="outlined" size="small" color="error">
                                Cancel Subscription
                            </Button>
                        </Box>
                    </Paper>
                </Grid>

                {/* User Details Section */}
                <Grid item xs={12} md={6}>
                    <Paper
                        elevation={0}
                        sx={{
                            p: 2,
                            border: `1px solid ${theme.palette.divider}`,
                            borderRadius: 2,
                            background: '#F2F7F8',
                            boxShadow: 3,
                            height: '100%'
                        }}
                    >
                        <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 2 }}>
                            <UserIcon color="primary" />
                            <Typography variant="h6">User Details</Typography>
                        </Stack>

                        <TableContainer>
                            <Table size="small">
                                <TableHead>
                                    <TableRow sx={{ '& td': { color: 'black' } }}>
                                        <TableCell sx={{ width: '40%' }}>Attribute</TableCell>
                                        <TableCell sx={{ width: '60%' }}>Value</TableCell>
                                    </TableRow>
                                </TableHead>
                                <TableBody>
                                    <TableRow sx={{ '& td': { color: 'black' } }}>
                                        <TableCell>Full Name</TableCell>
                                        <TableCell>{row.user.name}</TableCell>
                                    </TableRow>
                                    <TableRow sx={{ '& td': { color: 'black' } }}>
                                        <TableCell>First Name</TableCell>
                                        <TableCell>{row.user.first_name}</TableCell>
                                    </TableRow>
                                    <TableRow sx={{ '& td': { color: 'black' } }}>
                                        <TableCell>Last Name</TableCell>
                                        <TableCell>{row.user.last_name}</TableCell>
                                    </TableRow>
                                    <TableRow sx={{ '& td': { color: 'black' } }}>
                                        <TableCell>Email</TableCell>
                                        <TableCell>{row.user.email}</TableCell>
                                    </TableRow>
                                    <TableRow sx={{ '& td': { color: 'black' } }}>
                                        <TableCell>Customer ID</TableCell>
                                        <TableCell>{row.stripe_customer_id}</TableCell>
                                    </TableRow>
                                    <TableRow sx={{ '& td': { color: 'black' } }}>
                                        <TableCell>Subscription ID</TableCell>
                                        <TableCell>{row.stripe_subscription_id}</TableCell>
                                    </TableRow>
                                </TableBody>
                            </Table>
                        </TableContainer>
                    </Paper>
                </Grid>
            </Grid>

            {/* Dates Section */}
            <Paper
                elevation={0}
                sx={{ p: 2, mt: 2, border: `1px solid ${theme.palette.divider}`, borderRadius: 2, background: '#F2F7F8', boxShadow: 3 }}
            >
                <TableContainer>
                    <Table size="small">
                        <TableHead>
                            <TableRow sx={{ '& td': { color: 'black' } }}>
                                <TableCell sx={{ width: '25%' }}>Date Type</TableCell>
                                <TableCell sx={{ width: '35%' }}>Value</TableCell>
                                <TableCell sx={{ width: '40%' }}>Notes</TableCell>
                            </TableRow>
                        </TableHead>
                        <TableBody>
                            <TableRow sx={{ '& td': { color: 'black' } }}>
                                <TableCell>Created At</TableCell>
                                <TableCell>{new Date(row.createdAt).toLocaleString()}</TableCell>
                                <TableCell>When subscription was created</TableCell>
                            </TableRow>
                            <TableRow sx={{ '& td': { color: 'black' } }}>
                                <TableCell>Current Period Start</TableCell>
                                <TableCell>{row.currentPeriodStart ? new Date(row.currentPeriodStart).toLocaleString() : 'N/A'}</TableCell>
                                <TableCell>Start of current billing cycle</TableCell>
                            </TableRow>
                            <TableRow sx={{ '& td': { color: 'black' } }}>
                                <TableCell>Current Period End</TableCell>
                                <TableCell>{row.currentPeriodEnd ? new Date(row.currentPeriodEnd).toLocaleString() : 'N/A'}</TableCell>
                                <TableCell>End of current billing cycle</TableCell>
                            </TableRow>
                            <TableRow sx={{ '& td': { color: 'black' } }}>
                                <TableCell>Trial End</TableCell>
                                <TableCell>{row.trialEnd ? new Date(row.trialEnd).toLocaleString() : 'N/A'}</TableCell>
                                <TableCell>When trial period ends (if applicable)</TableCell>
                            </TableRow>
                        </TableBody>
                    </Table>
                </TableContainer>
            </Paper>
        </Box>
    );
};

export default RenderDetails;
